//! Destination owner/identity staging and immutable source admission.
use super::*;
#[test]
fn inert_document_import_storage_copy_refusal_no_slot_backing_and_fresh_recovery(){
 let mut doc=crate::html::parse_loaded_document("<html><body><span id=source data-note=old>original</span></body></html>",&||Ok(())).unwrap();doc.scripting_enabled=true;let source_index=(0..doc.nodes.len()).find(|&n|doc.attr(n,"id")==Some("source")).unwrap();let mut forms=Forms::new(&doc);let mut page=Page::new();assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);let mut b=Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state};let Value::Host(target)=b.create_xml_document(MAIN_IMPLEMENTATION,&[Value::Null,Value::String(String::new())]).unwrap()else{panic!("target")};b.state.node_limit=b.doc.nodes.len();b.reserve_inert_entries(2,0,2).unwrap();let source=node_handle(source_index);let parent=b.state.tree.parents[source_index];let before=(b.state.retained,b.state.inert_documents.backing_bytes(),b.state.inert_documents.entries.len(),b.state.inert_documents.generated.len(),b.doc.nodes.len(),b.state.dom_commits);let limit=b.state.retained_limit;let copies=b.state.copy_work;
 for storage in [true,false]{if storage{b.state.retained_limit=before.0+size_of::<u32>();}else{b.state.copy_work=0;}assert!(b.import_into_inert_document(target,source,true).is_err());assert_eq!((b.state.retained,b.state.inert_documents.backing_bytes(),b.state.inert_documents.entries.len(),b.state.inert_documents.generated.len(),b.doc.nodes.len(),b.state.dom_commits),before);assert_eq!(b.state.tree.parents[source_index],parent);assert!(b.state.inert_documents.node(source).is_none());assert_eq!(b.doc.attr(source_index,"data-note"),Some("old"));b.state.retained_limit=limit;b.state.copy_work=copies;}
 let Value::Host(copy)=b.import_into_inert_document(target,source,true).unwrap()else{panic!("copy")};assert!(copy>=FIRST_ENTRY);let root=b.state.inert_documents.node(copy).unwrap();assert_eq!(root.owner,target);assert_eq!(root.parent,None);let child=root.children[0];assert_eq!(b.state.inert_documents.node(child).unwrap().owner,target);assert_eq!(b.state.inert_documents.node(child).unwrap().parent,Some(copy));let links=b.state.inert_documents.entries[before.2..].iter().map(|e|match e{Entry::Node(n)=>n.children.capacity()*size_of::<u32>(),_=>panic!("actual no-slot node")}).sum::<usize>();let snapshots=b.state.inert_documents.generated[before.3..].iter().map(|s|node_bytes(&s.node)+size_of::<Node>()+2*size_of::<usize>()+match &s.node.kind{NodeKind::Element{tag,href,..}=>tag.capacity()+href.as_ref().map_or(0,String::capacity),_=>0}).sum::<usize>();assert_eq!(b.state.retained,before.0+links+snapshots+b.state.inert_documents.backing_bytes()-before.1);assert_eq!(b.doc.nodes.len(),before.4);assert_eq!(b.state.tree.parents[source_index],parent);assert!(b.state.inert_documents.node(source).is_none());let Kind::Document(record)=&b.state.inert_documents.node(target).unwrap().kind else{panic!("document")};assert_eq!(record.html,None);
}
